import{_ as t,o as n,c as r,a3 as s}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Erfolgsseite und Weiterleitung","description":"Festlegen, was nach dem Absenden eines Formulars passiert.","frontmatter":{"title":"Erfolgsseite und Weiterleitung","description":"Festlegen, was nach dem Absenden eines Formulars passiert."},"headers":[],"relativePath":"formulare/erfolgsseite.md","filePath":"formulare/erfolgsseite.md","lastUpdated":1788108473000}'),i={name:"formulare/erfolgsseite.md"};function a(l,e,d,o,u,h){return n(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="erfolgsseite-und-weiterleitung" tabindex="-1">Erfolgsseite und Weiterleitung <a class="header-anchor" href="#erfolgsseite-und-weiterleitung" aria-label="Permalink to &quot;Erfolgsseite und Weiterleitung&quot;">​</a></h1><p>Der Bereich <strong>Erfolgsseite</strong> im Reiter <em>Layout</em> bestimmt, was Ausfüllende nach dem Absenden sehen.</p><h2 id="bestatigungstext" tabindex="-1">Bestätigungstext <a class="header-anchor" href="#bestatigungstext" aria-label="Permalink to &quot;Bestätigungstext&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Einstellung</th><th>Voreinstellung</th></tr></thead><tbody><tr><td><strong>Titel</strong></td><td><em>Vielen Dank!</em></td></tr><tr><td><strong>Nachricht</strong></td><td><em>Ihre Antwort ist bei uns eingegangen.</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Sagen Sie, wie es weitergeht</p><p>Die Voreinstellung bestätigt nur den Eingang. Nützlicher ist, was als Nächstes passiert: „Wir melden uns innerhalb von zwei Werktagen.&quot; oder „Sie erhalten gleich eine Bestätigung per E-Mail.&quot;</p><p>Das reduziert Nachfragen spürbar — besonders, wenn ein <a href="/flows/was-ist-ein-flow">Flow</a> im Hintergrund eine Bestätigungsmail verschickt.</p></div><h2 id="aktion-nach-dem-absenden" tabindex="-1">Aktion nach dem Absenden <a class="header-anchor" href="#aktion-nach-dem-absenden" aria-label="Permalink to &quot;Aktion nach dem Absenden&quot;">​</a></h2><p>Drei Möglichkeiten:</p><table tabindex="0"><thead><tr><th>Aktion</th><th>Verhalten</th></tr></thead><tbody><tr><td><strong>Keine Aktion</strong></td><td>Es bleibt bei der Erfolgsmeldung</td></tr><tr><td><strong>Erneut ausfüllen</strong></td><td>Ein Button öffnet das Formular noch einmal</td></tr><tr><td><strong>Auf Webseite weiterleiten</strong></td><td>Weiterleitung auf eine angegebene <strong>Webseite</strong></td></tr></tbody></table><h3 id="erneut-ausfullen" tabindex="-1">Erneut ausfüllen <a class="header-anchor" href="#erneut-ausfullen" aria-label="Permalink to &quot;Erneut ausfüllen&quot;">​</a></h3><p>Für Fälle, in denen dieselbe Person mehrere Eingaben hintereinander macht — Inventuren, Erfassung mehrerer Positionen, Anmeldung mehrerer Personen.</p><p>Die Button-Beschriftung stellen Sie unter <strong>Text &#39;Weiteres Formular senden&#39;</strong> ein; für Ausfüllende heißt sie voreingestellt <em>Weitere Antworten senden</em>.</p><h3 id="auf-webseite-weiterleiten" tabindex="-1">Auf Webseite weiterleiten <a class="header-anchor" href="#auf-webseite-weiterleiten" aria-label="Permalink to &quot;Auf Webseite weiterleiten&quot;">​</a></h3><p>Leitet auf eine Adresse Ihrer Wahl weiter — etwa auf Ihre Website, eine Dankesseite oder eine Terminbuchung.</p><p>Das Feld heißt <strong>Webseite</strong>, Platzhalter <code>https://www...</code>.</p><div class="tip custom-block"><p class="custom-block-title">Tarifabhängig</p><p>Die Weiterleitung steht nicht in allen Tarifen zur Verfügung.</p></div><h2 id="auslosen-durch" tabindex="-1">Auslösen durch <a class="header-anchor" href="#auslosen-durch" aria-label="Permalink to &quot;Auslösen durch&quot;">​</a></h2><p>Bei <em>Erneut ausfüllen</em> und <em>Auf Webseite weiterleiten</em> bestimmen Sie zusätzlich den Zeitpunkt:</p><table tabindex="0"><thead><tr><th>Auswahl</th><th>Verhalten</th></tr></thead><tbody><tr><td><strong>Button klicken</strong></td><td>Die Person entscheidet selbst</td></tr><tr><td><strong>Direkt nach absenden</strong></td><td>Sofort, ohne Bestätigung</td></tr><tr><td><strong>nach 5 Sekunden</strong></td><td>Die Erfolgsmeldung bleibt kurz stehen</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">„Direkt nach absenden&quot; überspringt die Bestätigung</p><p>Ausfüllende sehen dann <strong>keine</strong> Rückmeldung, dass etwas angekommen ist — sie landen unmittelbar auf der Zielseite. Das verunsichert und führt zu Doppeleinsendungen.</p><p><strong>nach 5 Sekunden</strong> ist fast immer die bessere Wahl: Die Bestätigung wird gelesen, die Weiterleitung erfolgt trotzdem automatisch.</p></div><div class="tip custom-block"><p class="custom-block-title">Button-Text sagt, wohin es geht</p><p>Bei <em>Button klicken</em> lässt sich die Beschriftung frei wählen. „Zur Terminbuchung&quot; ist hilfreicher als „Weiter&quot; — die Person weiß, was sie erwartet.</p></div><h2 id="produkthinweis" tabindex="-1">Produkthinweis <a class="header-anchor" href="#produkthinweis" aria-label="Permalink to &quot;Produkthinweis&quot;">​</a></h2><p><strong>Produkt Hinweis ausblenden</strong> entfernt den Hinweis <em>Erstell dein eigenes kostenloses Formular mit …</em>. Tarifabhängig.</p><h2 id="zusammenspiel-mit-anderen-einstellungen" tabindex="-1">Zusammenspiel mit anderen Einstellungen <a class="header-anchor" href="#zusammenspiel-mit-anderen-einstellungen" aria-label="Permalink to &quot;Zusammenspiel mit anderen Einstellungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wechselwirkung</th></tr></thead><tbody><tr><td><a href="/formulare/speichern-und-fortsetzen">Speichern um später fortzufahren</a></td><td>Eigene Bestätigung <em>Formular wurde gespeichert!</em></td></tr><tr><td><strong>Automatisch absenden</strong></td><td>Die Erfolgsseite erscheint sofort beim Laden</td></tr><tr><td><strong>Absenden-Button ausblenden</strong></td><td>Ohne Absenden wird die Erfolgsseite nie erreicht</td></tr><tr><td><a href="/formulare/mehrsprachig">Mehrsprachigkeit</a></td><td>Titel, Nachricht und Button-Text sind übersetzbar</td></tr></tbody></table><h2 id="was-ausfullende-sonst-noch-sehen" tabindex="-1">Was Ausfüllende sonst noch sehen <a class="header-anchor" href="#was-ausfullende-sonst-noch-sehen" aria-label="Permalink to &quot;Was Ausfüllende sonst noch sehen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Text</th></tr></thead><tbody><tr><td>Absenden</td><td><em>Absenden</em></td></tr><tr><td>Zurück zum Formular</td><td><em>Zurück zum Formular</em></td></tr><tr><td>Bei einem Fehler</td><td><em>Ups - Fehler</em></td></tr></tbody></table><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/formulare/formular-erstellen">Formular erstellen</a></li><li><a href="/formulare/speichern-und-fortsetzen">Speichern und später fortsetzen</a></li><li><a href="/formulare/gestaltung">Gestaltung</a></li></ul>',28)])])}const c=t(i,[["render",a]]);export{m as __pageData,c as default};
